document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("holdersGrid"),t=IRWR.groupBy("holderName");e.innerHTML=Object.keys(t).sort().map(e=>{const a=t[e],d=a[0];return`\n      <div class="hcard reveal in tilt" data-holder="${IRWR.escapeHtml(e)}">\n        <div class="hface">\n          <div class="hph"><img class="photo" src="${IRWR.photoUrl(d,"-holder",500,700)}" alt="${IRWR.escapeHtml(e)}" loading="lazy" width="500" height="700"></div>\n          <div class="hname">${IRWR.escapeHtml(e)}</div>\n          <div class="hmeta">${IRWR.escapeHtml(d.country||"International")} · ${IRWR.escapeHtml(d.category)} · ${IRWR.escapeHtml(d.id)}</div>\n        </div>\n        <div class="hface hback">\n          <div>\n            <div class="hname">${IRWR.escapeHtml(d.title)}</div>\n            <div class="hmeta">${a.length} record${a.length>1?"s":""} on file</div>\n          </div>\n        </div>\n      </div>\n    `}).join(""),IRWR.initTilt(".hcard"),e.addEventListener("click",e=>{const t=e.target.closest(".hcard");t&&IRWR.openHolderModal(t.dataset.holder)});const a=new URLSearchParams(location.search).get("holder");a&&t[a]&&IRWR.openHolderModal(a)});